import 'package:meta/meta.dart';

import '../../settings/domain/app_settings.dart';

/// The checksums of one page's two files.
typedef SvgPageEntry = ({String svgSha256, String jsonSha256, int bytes});

/// One archive holding every page's SVG or JSON file, for downloading the
/// whole Mushaf at once.
typedef SvgArchive = ({String name, Uri url, String sha256, int bytes});

/// The list of the printed Mushaf's page files: where they are downloaded
/// from and the SHA-256 each must match before the app will use it.
///
/// Generated by `tool/build_svg_manifest.py` from the source files, never
/// edited by hand. See `docs/QURAN_SOURCES.md`, section 14.
@immutable
class SvgManifest {
  /// Creates a manifest of [pages] served under [base].
  SvgManifest({
    required this.edition,
    required this.base,
    required this.packedBytes,
    required List<SvgArchive> archives,
    required List<SvgPageEntry> pages,
  }) : archives = List.unmodifiable(archives),
       pages = List.unmodifiable(pages);

  /// Bundled asset holding the manifest of [edition].
  static String assetOf(MushafEdition edition) =>
      'assets/quran/svg/${edition.id.replaceAll('-', '_')}_manifest.json';

  /// SHA-256 of each manifest's content, compactly re-encoded
  /// (`jsonEncode(jsonDecode(file))`), checked by a test. Hashing the content
  /// instead of the bytes keeps the check true when an editor re-indents the
  /// file, and still fails on any changed value.
  static const Map<MushafEdition, String> contentSha256 = {
    MushafEdition.hafs:
        '198cd724391c97dd1c93d8bf5db5961403a1dce31d901293baa46442b7f24cc4',
    MushafEdition.shubah:
        '59ad875d1ab8f84c45c68adf22e2c252f7221b51f68f299dafbfb9714977ffa9',
    MushafEdition.warsh:
        'df541939a31ce75511ce73eabe02fdd9974157828566d5d16d747e529bf02ff3',
    MushafEdition.qalon:
        'da6f77792cc2047a3d28af22ef2b9f6564337c4c1724a30e3259236bd2369084',
    MushafEdition.douri:
        '14e2a34164c3ccd8507cdda714629d9a5e3870f3ede4cbefe3efea22fce7a90e',
  };

  /// Name of the edition, used as its folder on the device.
  final String edition;

  /// Folder the files are served from; versioned and immutable.
  final Uri base;

  /// Size of every page together as kept on the device, compressed: what
  /// the offline pack costs in storage.
  final int packedBytes;

  /// The archives that together hold every page file.
  final List<SvgArchive> archives;

  /// Size of the archives together: what the offline download costs in data.
  int get downloadBytes =>
      archives.fold(0, (sum, archive) => sum + archive.bytes);

  /// One entry per page; index 0 is page 1.
  final List<SvgPageEntry> pages;

  /// Number of pages.
  int get pageCount => pages.length;

  /// Size of every file together, as downloaded.
  int get totalBytes => pages.fold(0, (sum, page) => sum + page.bytes);

  /// The entry of [page], 1-based.
  SvgPageEntry entry(int page) => pages[page - 1];

  /// File name of [page] with [extension] (`svg` or `json`), as served.
  static String fileName(int page, String extension) =>
      '${page.toString().padLeft(3, '0')}.$extension';

  /// Address of a file of [page].
  Uri url(int page, String extension) =>
      base.replace(path: '${base.path}/${fileName(page, extension)}');
}
